3	/**
4	 * Game surface — one column, three zones, dominance top to bottom:
5	 *   1. Question zone — optional small-caps category eyebrow (metadata
6	 *      `category` + the round attribute), then the current question in very
7	 *      large clamp-scaled Fraunces display type (shorter question ⇒ bigger
8	 *      type). The entrance is a chalk-write word stagger (~40ms/word) — it
9	 *      REPLACES the old block rise, keeping the three-intentional-animations
10	 *      discipline. Reveals swap to the answer "stamped" in Fraunces italic
11	 *      with a correct/incorrect color pulse (pulse fires off the `reveal`
12	 *      beat, not attribute propagation). Optional `choices` render as a 2×2
13	 *      letter-chip grid; optional `eliminated` indices get a chalk strike +
14	 *      dim (50/50). Picture questions render inside a proper frame.
15	 *   2. Timer zone — thin draining bar tied to the answer window. When the
16	 *      window carries `steal:true` (optional seam key) a STEAL eyebrow lands
17	 *      over a hotter, faster-pulsing bar. Display only: it adjudicates
18	 *      nothing, ticks nothing, and rests when closed or when the heartbeat
19	 *      watchdog degrades to calm-scoreboard mode.
20	 *   3. Score rail — persistent player chips in presentation-only rank order
21	 *      (the leader flag itself always comes from the agent): FLIP glide when
22	 *      rank order changes, ~450ms count-roll on score changes (tabular-nums
23	 *      keeps width stable), streak flame at 2+, crown on the agent-flagged
24	 *      leader, single pulse on the scoring player at adjudication.
25	 * Plus persistent mode badges (discreet "18+" in adult mode, "pictures" when
26	 * the optional media_mode attribute says so) and a discreet skip affordance
27	 * (`lily_control.skip`).
28	 */
29	
30	import { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
31	import { Crown, Flame, SkipForward } from '@phosphor-icons/react';
32	import { cn } from '@/lib/utils';
33	import type { LilyAnswerWindow, LilyGameState } from '@/components/lily/state';
34	import type { ClarifyBeat, LockBeat, RevealBeat } from '@/components/lily/lily-surface';
