39	function prefersReducedMotion(): boolean {
40	  return (
41	    typeof window !== 'undefined' &&
42	    typeof window.matchMedia === 'function' &&
43	    window.matchMedia('(prefers-reduced-motion: reduce)').matches
44	  );
45	}
