47	/** Shorter question ⇒ bigger type. Returns a CSS clamp() font-size. */
48	function questionFontSize(text: string): string {
49	  const length = Math.max(text.trim().length, 1);
50	  const idealVw = Math.min(9.5, Math.max(3.4, 27 / Math.sqrt(length)));
51	  return `clamp(1.6rem, ${idealVw.toFixed(2)}vw + 0.9rem, 4.75rem)`;
52	}
