54	/** "HISTORY — ROUND TWO" shape: rounds read as words where sensible. */
55	const ROUND_WORDS = ['one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];
56	function roundWord(round: number): string {
57	  return ROUND_WORDS[round - 1] ?? String(round);
58	}
