60	/**
61	 * Chalk-write entrance: the question lands word by word (~40ms/word stagger,
62	 * each word a quick opacity + 2px rise). Re-keyed per question by the
63	 * caller. Reduced motion → the container does a single opacity swap and the
64	 * words render static (globals.css).
65	 */
66	function LilyChalkText({
67	  text,
68	  className,
69	  style,
70	}: {
71	  text: string;
72	  className?: string;
73	  style?: React.CSSProperties;
74	}) {
75	  const words = text.split(/\s+/).filter(Boolean);
76	  return (
