90	/**
91	 * Count-roll numeral (~450ms, tabular-nums so width holds): animates from
92	 * the previously *rendered* value to the new one. `previous` survives chip
93	 * remounts because the rail holds it per player. Reduced motion → instant.
94	 */
95	function RollingScore({
96	  value,
97	  previous,
98	  className,
99	}: {
100	  value: number;
101	  previous: number;
102	  className?: string;
103	}) {
104	  const [display, setDisplay] = useState(previous);
105	  const displayRef = useRef(previous);
106	
107	  useEffect(() => {
108	    const from = displayRef.current;
109	    if (from === value || prefersReducedMotion()) {
110	      displayRef.current = value;
111	      setDisplay(value);
112	      return;
113	    }
114	    const startedAt = performance.now();
115	    let frame = 0;
116	    const tick = (now: number) => {
117	      const t = Math.min(1, (now - startedAt) / 450);
118	      const eased = 1 - (1 - t) ** 3;
119	      const next = Math.round(from + (value - from) * eased);
120	      displayRef.current = next;
121	      setDisplay(next);
122	      if (t < 1) frame = requestAnimationFrame(tick);
123	    };
124	    frame = requestAnimationFrame(tick);
125	    return () => cancelAnimationFrame(frame);
126	  }, [value]);
127	
128	  return <span className={cn('tabular-nums', className)}>{display}</span>;
129	}
