133	 * agent-published window (opened_at + duration_ms); nothing here decides
134	 * anything — when the agent closes the window the bar rests regardless.
135	 * `steal` swaps the fill to the hotter, faster-pulsing treatment.
136	 */
137	function LilyTimerBar({
