392	  // documented fallback for slow/dropped reveal METADATA, and the verdict
393	  // ("Saturn — Maya got it") used to collapse to a bare "Revealing…" the
394	  // moment the pulse timer fired. The latch survives the pulse clear and
395	  // resets when the reveal phase ends.
396	  const [heldRevealBeat, setHeldRevealBeat] = useState<RevealBeat | null>(null);
397	  useEffect(() => {
398	    if (revealBeat) setHeldRevealBeat(revealBeat);
399	  }, [revealBeat]);
400	  useEffect(() => {
401	    if (!revealPhase) setHeldRevealBeat(null);
402	  }, [revealPhase]);
403	  const beatReveal = revealBeat ?? heldRevealBeat;
404	
405	  const revealAnswer = reveal?.answer ?? beatReveal?.answer ?? null;
406	  const revealActive = revealPhase && revealAnswer !== null;
407	
408	  // Reveal TTL: a reveal that outlives its moment (backend stall, dropped
409	  // update) must not read as a frozen screen — collapse to a neutral
410	  // "next one's coming" hold after 12s. Any state change re-arms it.
411	  const [revealExpired, setRevealExpired] = useState(false);
412	  useEffect(() => {
