836	              'lily-pill-enter lily-skip pointer-events-auto relative flex min-h-[44px] shrink-0 touch-none select-none items-center gap-1.5 overflow-hidden rounded-full border border-[var(--border)] bg-transparent px-4 text-[11px] font-medium uppercase tracking-[0.16em] text-[var(--text-muted)] transition-colors hover:text-[var(--text)] disabled:opacity-40',
837	              holdingSkip && 'lily-skip-holding',
838	            )}
839	          >
840	            <SkipForward size={14} weight="light" aria-hidden />
841	            hold to skip
842	          </button>
843	        )}
844	      </div>
845	      {skipFailed && (
846	        <p
847	          className="mt-2 text-center text-xs text-[var(--lily-wrong)]"
848	          role="alert"
849	        >
850	          Lily didn’t catch that — hold to try again, or say “skip”.
851	        </p>
852	      )}
853	    </div>
854	  );
