'use client';

/**
 * Game surface — one column, three zones, dominance top to bottom:
 *   1. Question zone — optional small-caps category eyebrow (metadata
 *      `category` + the round attribute), then the current question in very
 *      large clamp-scaled Fraunces display type (shorter question ⇒ bigger
 *      type). The entrance is a chalk-write word stagger (~40ms/word) — it
 *      REPLACES the old block rise, keeping the three-intentional-animations
 *      discipline. Reveals swap to the answer "stamped" in Fraunces italic
 *      with a correct/incorrect color pulse (pulse fires off the `reveal`
 *      beat, not attribute propagation). Optional `choices` render as a 2×2
 *      letter-chip grid; optional `eliminated` indices get a chalk strike +
 *      dim (50/50). Picture questions render inside a proper frame.
 *   2. Timer zone — thin draining bar tied to the answer window. When the
 *      window carries `steal:true` (optional seam key) a STEAL eyebrow lands
 *      over a hotter, faster-pulsing bar. Display only: it adjudicates
 *      nothing, ticks nothing, and rests when closed or when the heartbeat
 *      watchdog degrades to calm-scoreboard mode.
 *   3. Score rail — persistent player chips in presentation-only rank order
 *      (the leader flag itself always comes from the agent): FLIP glide when
 *      rank order changes, ~450ms count-roll on score changes (tabular-nums
 *      keeps width stable), streak flame at 2+, crown on the agent-flagged
 *      leader, single pulse on the scoring player at adjudication.
 * Plus persistent mode badges (discreet "18+" in adult mode, "pictures" when
 * the optional media_mode attribute says so) and a discreet skip affordance
 * (`lily_control.skip`).
 */

import { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { Crown, Flame, SkipForward } from '@phosphor-icons/react';
import { cn } from '@/lib/utils';
import type { LilyAnswerWindow, LilyGameState } from '@/components/lily/state';
import type { ClarifyBeat, LockBeat, RevealBeat } from '@/components/lily/lily-surface';

/** Hold-to-skip dwell: an accidental tap must not kill a question. */
const SKIP_HOLD_MS = 600;

function prefersReducedMotion(): boolean {
  return (
    typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
}

/** Shorter question ⇒ bigger type. Returns a CSS clamp() font-size. */
function questionFontSize(text: string): string {
  const length = Math.max(text.trim().length, 1);
  const idealVw = Math.min(9.5, Math.max(3.4, 27 / Math.sqrt(length)));
  return `clamp(1.6rem, ${idealVw.toFixed(2)}vw + 0.9rem, 4.75rem)`;
}

/** "HISTORY — ROUND TWO" shape: rounds read as words where sensible. */
const ROUND_WORDS = ['one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];
function roundWord(round: number): string {
  return ROUND_WORDS[round - 1] ?? String(round);
}

/**
 * Chalk-write entrance: the question lands word by word (~40ms/word stagger,
 * each word a quick opacity + 2px rise). Re-keyed per question by the
 * caller. Reduced motion → the container does a single opacity swap and the
 * words render static (globals.css).
 */
function LilyChalkText({
  text,
  className,
  style,
}: {
  text: string;
  className?: string;
  style?: React.CSSProperties;
}) {
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <p className={cn('lily-chalk lily-question-text', className)} style={style}>
      {words.map((word, index) => (
        <Fragment key={`${index}-${word}`}>
          <span className="lily-word" style={{ animationDelay: `${index * 40}ms` }}>
            {word}
          </span>
          {index < words.length - 1 ? ' ' : null}
        </Fragment>
      ))}
    </p>
  );
}

/**
 * Count-roll numeral (~450ms, tabular-nums so width holds): animates from
 * the previously *rendered* value to the new one. `previous` survives chip
 * remounts because the rail holds it per player. Reduced motion → instant.
 */
function RollingScore({
  value,
  previous,
  className,
}: {
  value: number;
  previous: number;
  className?: string;
}) {
  const [display, setDisplay] = useState(previous);
  const displayRef = useRef(previous);

  useEffect(() => {
    const from = displayRef.current;
    if (from === value || prefersReducedMotion()) {
      displayRef.current = value;
      setDisplay(value);
      return;
    }
    const startedAt = performance.now();
    let frame = 0;
    const tick = (now: number) => {
      const t = Math.min(1, (now - startedAt) / 450);
      const eased = 1 - (1 - t) ** 3;
      const next = Math.round(from + (value - from) * eased);
      displayRef.current = next;
      setDisplay(next);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [value]);

  return <span className={cn('tabular-nums', className)}>{display}</span>;
}

/**
 * Display-only draining bar. Fraction is derived every frame from the
 * agent-published window (opened_at + duration_ms); nothing here decides
 * anything — when the agent closes the window the bar rests regardless.
 * `steal` swaps the fill to the hotter, faster-pulsing treatment.
 */
function LilyTimerBar({
  window: answerWindow,
  resting,
  steal,
}: {
  window: LilyAnswerWindow | null;
  resting: boolean;
  steal: boolean;
}) {
  const fillRef = useRef<HTMLDivElement | null>(null);

  const active =
    !resting &&
    !!answerWindow &&
    answerWindow.open &&
    answerWindow.durationMs > 0 &&
    answerWindow.openedAtMs !== null;

  useEffect(() => {
    const fill = fillRef.current;
    if (!fill) return;
    if (!active || !answerWindow || answerWindow.openedAtMs === null) {
      fill.style.transform = 'scaleX(0)';
      return;
    }

    let frame = 0;
    const tick = () => {
      const elapsed = Date.now() - answerWindow.openedAtMs!;
      const remaining = 1 - elapsed / answerWindow.durationMs;
      const fraction = Math.min(1, Math.max(0, remaining));
      fill.style.transform = `scaleX(${fraction.toFixed(4)})`;
      // Urgency shift (audit #4): the fill warms to coral past ~33%
      // remaining — CSS transitions the color off this flag.
      fill.dataset.lilyLow = fraction > 0 && fraction < 0.33 ? 'true' : 'false';
      if (fraction > 0) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active, answerWindow]);

  return (
    <div
      className={cn(
        'h-2 w-full max-w-[34rem] overflow-hidden rounded-full bg-[var(--border)] transition-[opacity,box-shadow] duration-300',
        active
          ? 'opacity-100 shadow-[0_0_14px_var(--lily-accent-soft)]'
          : 'opacity-35',
      )}
      role="presentation"
    >
      <div
        ref={fillRef}
        className={cn('lily-timer-fill h-full w-full origin-left rounded-full', steal && 'lily-steal-fill')}
        style={{ transform: 'scaleX(0)' }}
      />
    </div>
  );
}

function PlayerChip({
  name,
  score,
  previousScore,
  streak,
  leader,
  clarify = false,
  locked = false,
  unclaimed = false,
}: {
  name: string;
  score: number;
  /** Last rendered score (held by the rail) — the count-roll's start value. */
  previousScore: number;
  streak: number;
  leader: boolean;
  /** "You're being addressed" — double pulse in a distinct hue, not the scored pulse. */
  clarify?: boolean;
  /** "Answer locked in" — thin expanding ring, distinct from pulse and clarify. */
  locked?: boolean;
  /** Held/unbound point (WS-8): a scored point waiting for identity to bind. */
  unclaimed?: boolean;
}) {
  if (unclaimed) {
    // A real point with no owner yet: dashed hairline + muted ink so it reads
    // as pending, never as a competitor. Resolves when the merge/bind
    // re-publishes `players` and this row is replaced by the named chip.
    const points = score === 1 ? '1 point' : `${score} points`;
    return (
      <div
        data-lily-chip={`unclaimed:${name}`}
        data-lily-unclaimed="true"
        className="flex items-center gap-2 rounded-full border border-dashed border-[var(--border)] bg-transparent px-4 py-2"
        aria-label={`Unclaimed — ${points}, waiting to be claimed`}
      >
        <span className="text-sm font-medium uppercase tracking-[0.12em] text-[var(--text-muted)]">
          Unclaimed
        </span>
        <span className="tabular-nums text-sm font-semibold text-[var(--text-muted)]">{score}</span>
      </div>
    );
  }
  return (
    <div
      data-lily-chip={name}
      className={cn(
        clarify ? 'lily-chip-clarify' : locked ? 'lily-chip-lock' : 'lily-chip-pulse',
        'flex items-center gap-2 rounded-full border border-[var(--border)] bg-[var(--surface)] px-4 py-2 transition-shadow duration-300',
        // The leader chip carries the accent: hairline + a soft halo, so the
        // front-runner reads from tabletop distance, not just via the crown.
        leader &&
          'border-[var(--lily-accent)]/50 shadow-[0_0_16px_var(--lily-accent-soft)]',
      )}
      title={name}
    >
      {leader && (
        <Crown size={14} weight="light" aria-label="Leader" className="text-[var(--lily-accent)] opacity-80" />
      )}
      <span className="max-w-[9rem] truncate text-sm font-medium text-[var(--text)]">{name}</span>
      {/* Contrast guard: the accent never carries sub-18px text — chip
          numerals sit in the cream ink token. */}
      <RollingScore value={score} previous={previousScore} className="text-sm font-semibold text-[var(--text)]" />
      {streak >= 2 && (
        <span className="flex items-center gap-0.5 text-[var(--text-muted)]" aria-label={`${streak} in a row`}>
          <Flame size={13} weight="light" aria-hidden />
          <span className="tabular-nums text-[11px]">{streak}</span>
        </span>
      )}
    </div>
  );
}

/** MC round (optional metadata `choices`): 2×2 letter-chip card grid.
    Letter chips in the display face, option text in the base stack.
    Optional `eliminated` indices get the chalk strike + 50% dim (50/50). */
const CHOICE_LETTERS = ['A', 'B', 'C', 'D'];
function LilyChoices({ choices, eliminated }: { choices: string[]; eliminated: number[] }) {
  return (
    <div className="grid w-full max-w-[38rem] grid-cols-2 gap-2.5">
      {choices.map((choice, index) => {
        const struck = eliminated.includes(index);
        return (
          <div
            key={`${index}-${choice}`}
            style={{ animationDelay: `${index * 70}ms` }}
            className={cn(
              'lily-choice-enter relative flex items-center gap-3 rounded-xl border border-[var(--border)] bg-[var(--surface)]/70 px-4 py-3 text-left',
              struck && 'lily-choice-eliminated',
            )}
          >
            <span
              className="lily-display flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-[var(--lily-accent)]/35 bg-[var(--lily-accent-soft)] text-lg leading-none text-[var(--lily-accent)]"
              aria-hidden
            >
              {CHOICE_LETTERS[index]}
            </span>
            <span className="min-w-0 flex-1 text-sm leading-snug text-[var(--text)] sm:text-base">
              {choice}
              {struck && <span className="sr-only"> (eliminated)</span>}
            </span>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Picture round (optional metadata `image_url`, 2026-07-14 amendment):
 * image large in the question zone inside a proper frame (rounded, hairline
 * border, subtle mat), question text chalk-written below. Gracefully falls
 * back to exactly the text-only rendering while the image loads and when
 * it fails — absent/broken image means today's behavior.
 */
function LilyPictureQuestion({
  src,
  text,
  onShown,
}: {
  src: string;
  text: string;
  onShown?: (url: string) => void;
}) {
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading');

  const textOnly = (
    <LilyChalkText
      text={text}
      style={{ fontSize: questionFontSize(text) }}
      className="lily-display lily-wager-charge mx-auto max-w-[22ch] leading-[1.12] text-balance text-[var(--text)]"
    />
  );

  if (status === 'error') return textOnly;

  return (
    <div className="flex h-full min-h-0 w-full flex-col items-center justify-center gap-4">
      <div
        className={cn(
          'lily-question-enter lily-picture-frame flex min-h-0 max-w-full flex-1 items-center justify-center',
          status !== 'ready' && 'hidden',
        )}
      >
        {/* eslint-disable-next-line @next/next/no-img-element -- arbitrary remote host from room metadata; plain img keeps this path inert */}
        <img
          src={src}
          alt={`Picture question: ${text}`}
          onLoad={() => {
            setStatus('ready');
            // HOTFIX-005 X4: tell the agent the picture is actually up.
            onShown?.(src);
          }}
          onError={() => setStatus('error')}
          className="h-full min-h-0 w-auto max-w-full rounded-xl object-contain"
        />
      </div>
      {status === 'ready' ? (
        <LilyChalkText
          text={text}
          className="lily-display lily-wager-charge mx-auto max-w-[36ch] text-[clamp(1.1rem,2.2vw+0.6rem,1.9rem)] leading-[1.2] text-balance text-[var(--text)]"
        />
      ) : (
        <div className="flex min-h-0 flex-1 items-center">{textOnly}</div>
      )}
    </div>
  );
}

export function LilyGame({
  state,
  stale,
  revealBeat,
  clarifyBeat,
  lockBeat,
  onSkip,
  onImageShown,
}: {
  state: LilyGameState;
  stale: boolean;
  revealBeat: RevealBeat | null;
  clarifyBeat: ClarifyBeat | null;
  lockBeat: LockBeat | null;
  onSkip: () => Promise<boolean>;
  onImageShown?: (url: string) => void;
}) {
  const [skipping, setSkipping] = useState(false);
  const [skipFailed, setSkipFailed] = useState(false);
  const skipFailureTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const reveal = state.reveal;
  const revealPhase = state.phase === 'reveal' || state.phase === 'scores';

  // Latch the beat's reveal payload for the phase's lifetime. The surface
  // clears `revealBeat` 450 ms after the pulse (that timer exists so an
  // identical later verdict can re-pulse) — but the beat is also the
  // documented fallback for slow/dropped reveal METADATA, and the verdict
  // ("Saturn — Maya got it") used to collapse to a bare "Revealing…" the
  // moment the pulse timer fired. The latch survives the pulse clear and
  // resets when the reveal phase ends.
  const [heldRevealBeat, setHeldRevealBeat] = useState<RevealBeat | null>(null);
  useEffect(() => {
    if (revealBeat) setHeldRevealBeat(revealBeat);
  }, [revealBeat]);
  useEffect(() => {
    if (!revealPhase) setHeldRevealBeat(null);
  }, [revealPhase]);
  const beatReveal = revealBeat ?? heldRevealBeat;

  const revealAnswer = reveal?.answer ?? beatReveal?.answer ?? null;
  const revealActive = revealPhase && revealAnswer !== null;

  // Reveal TTL: a reveal that outlives its moment (backend stall, dropped
  // update) must not read as a frozen screen — collapse to a neutral
  // "next one's coming" hold after 12s. Any state change re-arms it.
  const [revealExpired, setRevealExpired] = useState(false);
  useEffect(() => {
    setRevealExpired(false);
    if (!revealPhase) return;
    const t = window.setTimeout(() => setRevealExpired(true), 12_000);
    return () => window.clearTimeout(t);
  }, [revealPhase, revealAnswer, state.questionNumber, state.phase]);

  // Supply-stall HOLD (WS-6 seam flag): a healthy-but-starved game sits in
  // the reveal phase while question generation is starved — the frozen stale
  // reveal the liveness watchdog can't catch (the agent is alive). An
  // explicit `next_question_ready === false` collapses the reveal to the
  // positive "next one's coming" hold immediately, instead of waiting out the
  // 12s reveal TTL. Distinct from `stale`: the agent is present and pushing.
  // NOT gated on revealPhase. The agent publishes next_question_ready
  // "false" whenever the game is running with nothing armed and nothing
  // prefetched — and most ways into that state leave the phase on
  // `question`, not reveal/scores: skip_question, flush_for_mode_switch,
  // on_answer_leak, and a delivery released after being cut too many
  // times. The flag was on the wire and the board rendered nothing for
  // all of them: no "next one's coming" badge, no announcement, just a
  // blank question zone. `null` until the backend publishes it, so only
  // an explicit false engages.
  const supplyHold = state.nextQuestionReady === false;
  const holding = revealExpired || supplyHold;

  const showingReveal = revealActive && !holding;
  const showingVerdict =
    revealPhase &&
    !holding &&
    (reveal !== null || beatReveal !== null);
  const displayText = revealPhase
    ? holding
      ? 'Next one’s coming…'
      : revealAnswer ?? 'Revealing…'
    : state.question;
  const questionLive = !stale && (state.phase === 'question' || state.phase === 'answering');

  // Optional seam surfaces — all render nothing when the key is absent.
  const eyebrowVisible = !!displayText && !revealPhase && !!state.category;
  const choicesVisible = !!displayText && !revealPhase && state.choices !== null;
  const stealActive =
    !stale && !!state.answerWindow && state.answerWindow.open && state.answerWindow.steal;

  // ── Score rail: presentation-only rank order + FLIP glide + count-roll ──
  // (The leader flag itself always comes from the agent — never computed
  // here; sorting rendered chips by the agent's committed scores is display
  // ordering, not adjudication.)
  // Deterministic tiebreak (leader flag, then name): a tied score must not
  // let the rail order flip between renders or place the crowned chip second.
  const rankedPlayers = [...state.players].sort(
    (a, b) =>
      // Unclaimed (held/unbound) points always trail the named roster — they
      // are a pending point, not a competitor on the board.
      Number(!!a.unclaimed) - Number(!!b.unclaimed) ||
      b.score - a.score ||
      Number(b.leader) - Number(a.leader) ||
      a.name.localeCompare(b.name),
  );
  const railRef = useRef<HTMLDivElement | null>(null);
  const chipRectsRef = useRef(new Map<string, DOMRect>());
  const prevOrderRef = useRef('');
  const orderSignature = rankedPlayers.map((p) => p.name).join('|');

  // Last rendered score per player — survives chip remounts (reveal/clarify
  // re-keys) so the count-roll always starts from what was on screen. Held
  // in state committed after paint (render must not read refs): on a score
  // change the render sees the OLD value (roll start), then the effect
  // commits the new one.
  const [prevScores, setPrevScores] = useState<ReadonlyMap<string, number>>(new Map());
  useEffect(() => {
    setPrevScores((previous) => {
      let changed = false;
      const next = new Map(previous);
      for (const player of state.players) {
        if (next.get(player.name) !== player.score) {
          next.set(player.name, player.score);
          changed = true;
        }
      }
      // Prune departed players (unbind/rename) — the map held every name
      // ever seen for the whole session.
      const live = new Set(state.players.map((player) => player.name));
      for (const name of next.keys()) {
        if (!live.has(name)) {
          next.delete(name);
          changed = true;
        }
      }
      return changed ? next : previous;
    });
  }, [state.players]);

  // FLIP (First-Last-Invert-Play via the Web Animations API): measure chip
  // positions each render; when the rank order changed, invert each moved
  // chip to its old spot and glide it home. Rects are keyed by player name
  // so pulse re-keys (element swaps) don't break continuity.
  useLayoutEffect(() => {
    const rail = railRef.current;
    if (!rail) return;
    const orderChanged = prevOrderRef.current !== '' && prevOrderRef.current !== orderSignature;
    prevOrderRef.current = orderSignature;
    const previousRects = chipRectsRef.current;
    const nextRects = new Map<string, DOMRect>();
    const animate = orderChanged && !prefersReducedMotion();
    for (const el of Array.from(rail.querySelectorAll<HTMLElement>('[data-lily-chip]'))) {
      const name = el.dataset.lilyChip;
      if (!name) continue;
      const rect = el.getBoundingClientRect();
      nextRects.set(name, rect);
      if (!animate) continue;
      const before = previousRects.get(name);
      if (!before) continue;
      const dx = before.left - rect.left;
      const dy = before.top - rect.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) continue;
      el.animate(
        [{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'translate(0, 0)' }],
        { duration: 320, easing: 'cubic-bezier(0.25, 1, 0.5, 1)' },
      );
    }
    chipRectsRef.current = nextRects;
  });

  // The skip RPC (default 10s LiveKit timeout) can outlive this component
  // — the game view unmounts on phase change while the call is in flight;
  // guard the post-await setState calls.
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const handleSkip = async () => {
    if (skipping) return;
    setSkipping(true);
    setSkipFailed(false);
    try {
      const ok = await onSkip();
      if (!ok && mountedRef.current) {
        setSkipFailed(true);
        if (skipFailureTimerRef.current) clearTimeout(skipFailureTimerRef.current);
        skipFailureTimerRef.current = setTimeout(() => {
          setSkipFailed(false);
          skipFailureTimerRef.current = null;
        }, 5000);
      }
    } finally {
      if (mountedRef.current) setSkipping(false);
    }
  };

  // Skip is press-and-hold (audit #6): one accidental tap must not kill a
  // question. ~600ms dwell with a visual fill; releasing early is a no-op.
  // Reduced motion: the hold is still required, the fill collapses to an
  // opacity shift (globals.css). Still the discreet adult-mode consent
  // affordance — same spot, same size, never buried in a menu.
  const [holdingSkip, setHoldingSkip] = useState(false);
  const skipHoldTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const beginSkipHold = () => {
    if (skipping || skipHoldTimerRef.current) return;
    setHoldingSkip(true);
    skipHoldTimerRef.current = setTimeout(() => {
      skipHoldTimerRef.current = null;
      setHoldingSkip(false);
      void handleSkip();
    }, SKIP_HOLD_MS);
  };
  const cancelSkipHold = () => {
    if (skipHoldTimerRef.current) {
      clearTimeout(skipHoldTimerRef.current);
      skipHoldTimerRef.current = null;
    }
    setHoldingSkip(false);
  };
  useEffect(() => {
    return () => {
      if (skipHoldTimerRef.current) clearTimeout(skipHoldTimerRef.current);
      if (skipFailureTimerRef.current) clearTimeout(skipFailureTimerRef.current);
    };
  }, []);

  return (
    <div className={cn('flex h-full w-full flex-col px-5 pb-3 pt-4 sm:px-8', stale && 'opacity-80')}>
      {/* Persistent header line: round position + mode badges. */}
      <div className="flex min-h-[1.75rem] items-center justify-between">
        <span className="tabular-nums text-[11px] font-medium uppercase tracking-[0.24em] text-[var(--text-muted)]">
          {state.round !== null && `Round ${state.round}`}
          {state.round !== null && state.questionNumber !== null && ' · '}
          {state.questionNumber !== null && `Q${state.questionNumber}`}
        </span>
        <span className="flex items-center gap-3">
          {stale && (
            <span className="text-[10px] uppercase tracking-[0.24em] text-[var(--text-muted)] opacity-60">
              · holding ·
            </span>
          )}
          {/* Supply-stall hold (WS-6): agent is live but starved. A quiet
              pulsing marker so the wait reads as alive, not frozen — and
              distinct copy from the stale watchdog's "· holding ·". */}
          {!stale && supplyHold && (
            <span
              className="lily-chip-pulse text-[10px] uppercase tracking-[0.24em] text-[var(--lily-accent)] opacity-80"
              data-lily-hold="supply"
            >
              · next one’s coming ·
            </span>
          )}
          {state.mediaMode === 'pictures' && (
            <span className="rounded-full border border-[var(--border)] px-2.5 py-0.5 text-[11px] font-medium tracking-[0.08em] text-[var(--text-muted)]">
              pictures
            </span>
          )}
          {state.mode === 'adult' && (
            // Contrast guard: accent stays on the hairline; the small text
            // itself sits in the cream ink token.
            <span className="rounded-full border border-[var(--lily-accent)] px-2.5 py-0.5 text-[11px] font-semibold tracking-[0.08em] text-[var(--text)]">
              18+
            </span>
          )}
        </span>
      </div>

      {/* 1 — Question zone (the identity moment). */}
      <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-5 px-1 text-center">
        {eyebrowVisible && (
          <p
            key={`eyebrow:${state.questionNumber}:${state.category}`}
            className="lily-question-enter lily-eyebrow text-[13px]"
          >
            {state.category}
            {state.round !== null && ` — round ${roundWord(state.round)}`}
          </p>
        )}
        {displayText && !revealPhase && state.imageUrl ? (
          // Re-key on the image/question pair so load state and entrance
          // reset exactly once per new picture question.
          <LilyPictureQuestion
            key={`picture:${state.imageUrl}:${displayText}`}
            src={state.imageUrl}
            text={displayText}
            onShown={onImageShown}
          />
        ) : displayText && revealPhase ? (
          // Reveal answer, "stamped": Fraunces italic, tracking slightly
          // tightened; the reveal beat drives the color pulse.
          <p
            key={`reveal:${displayText}`}
            style={{ fontSize: questionFontSize(displayText) }}
            className={cn(
              'lily-display mx-auto max-w-[22ch] leading-[1.12] text-balance',
              showingReveal
                ? [
                    'lily-reveal-stamp lily-reveal-pulse',
                    (beatReveal?.correct ?? reveal?.correct)
                      ? 'text-[var(--lily-correct)]'
                      : 'text-[var(--lily-wrong)]',
                  ]
                : 'text-[var(--text-muted)] opacity-70',
            )}
          >
            {displayText}
          </p>
        ) : displayText ? (
          // Chalk-write entrance; re-keyed per question. The wager charge
          // (and its one-time stamp) applies via data-lily-wager on the root.
          <LilyChalkText
            key={`question:${state.questionNumber ?? ''}:${displayText}`}
            text={displayText}
            style={{
              fontSize: choicesVisible
                ? 'clamp(1.35rem, 2.6vw + 0.8rem, 2.6rem)'
                : questionFontSize(displayText),
            }}
            className="lily-display lily-wager-charge mx-auto max-w-[22ch] leading-[1.12] text-balance text-[var(--text)]"
          />
        ) : (
          <p className="text-sm uppercase tracking-[0.22em] text-[var(--text-muted)] opacity-60">
            Lily has the floor
          </p>
        )}
        {choicesVisible && state.choices && (
          <LilyChoices
            key={`choices:${state.questionNumber ?? ''}`}
            choices={state.choices}
            eliminated={state.eliminated}
          />
        )}
        {/* Explicit verdict line: the reveal's who-got-it, visible for the
            whole reveal beat — the color pulse alone was too easy to miss. */}
        {showingVerdict && (
          <p
            key={`verdict:${state.questionNumber}`}
            // A beat behind the reveal stamp so the answer lands first,
            // then the who-got-it line.
            style={{ animationDelay: '140ms' }}
            className={cn(
              'lily-question-enter text-base font-medium uppercase tracking-[0.2em]',
              (beatReveal?.correct ?? reveal?.correct)
                ? 'text-[var(--lily-correct)]'
                : 'text-[var(--lily-wrong)]',
            )}
          >
            {(beatReveal?.correct ?? reveal?.correct)
              ? `${reveal?.winner ?? beatReveal?.winner ?? 'someone'} got it`
              : 'nobody got it'}
          </p>
        )}
      </div>

      {/* 2 — Timer zone. Silent; rests when the window is closed. The STEAL
          treatment rides the optional answer_window.steal key. */}
      <div className="flex flex-col items-center gap-2 pb-4 pt-2">
        {stealActive && (
          <span
            key={`steal:${state.questionNumber ?? ''}`}
            className="lily-question-enter lily-eyebrow text-[13px] font-semibold"
            // Inline: outranks the eyebrow's muted tone — steal reads in the
            // cream ink (never small-text accent; the BAR carries the heat).
            style={{ color: 'var(--text)' }}
          >
            steal
          </span>
        )}
        {/* Relaxed pacing (group prefs WO): the table asked for no time
            pressure, so the countdown never renders — the agent still owns
            the (stretched) window. The steal beat keeps its bar: a steal
            is a sprint in any pacing, and the frontend would otherwise
            give no cue that the floor is open. */}
        {(state.pacing !== 'relaxed' || stealActive) && (
          <LilyTimerBar window={state.answerWindow} resting={stale} steal={stealActive} />
        )}
      </div>

      {/* 3 — Score rail + discreet skip.

          mb-11 reserves the CORNER-PILL BAND. LilySurface anchors two
          controls over this component — "go back" (absolute bottom-4
          left-4) and the camera "show" toggle (absolute bottom-4 right-4)
          — and they live in a different component, so nothing here knew to
          leave room. The rail ran straight underneath both: live 2026-08-09
          the leftmost player's NAME was hidden behind the "go back" pill,
          leaving a chip reading just "2 🔥2", and the skip affordance sat
          under "show".

          The pills occupy 1rem (bottom-4) up to 3.5rem (that plus their
          40px min height). The root contributes pb-3 = 0.75rem, so 3rem
          here puts this row's bottom edge at 3.75rem — clear, with a
          quarter-rem of air rather than flush against them.

          Vertical, not horizontal: a left/right gutter wide enough for the
          pills would eat 16rem of a phone screen, and this row wraps. */}
      <div className="mb-12 flex flex-wrap items-end justify-between gap-3">
        <div
          ref={railRef}
          className="flex max-h-[7.5rem] min-w-0 flex-1 flex-wrap items-center gap-2 overflow-y-auto"
        >
          {rankedPlayers.map((player) => {
            // Re-keying the scoring player on the reveal beat remounts its
            // chip, replaying the single chip pulse at adjudication. Every
            // chip also pulses once when it first lands. The clarify beat
            // remounts the addressed player's chip with the distinct
            // double-pulse ("you're being addressed", not "you scored");
            // the lock beat with the thin expanding ring ("answer's in").
            // Unclaimed (held/unbound) points never take a beat pulse — the
            // reveal/clarify/lock beats all name a real bound player.
            if (player.unclaimed) {
              return (
                <PlayerChip
                  key={`unclaimed:${player.name}`}
                  name={player.name}
                  score={player.score}
                  previousScore={player.score}
                  streak={0}
                  leader={false}
                  unclaimed
                />
              );
            }
            const clarified = clarifyBeat !== null && clarifyBeat.name === player.name;
            const locked = lockBeat !== null && lockBeat.name === player.name;
            return (
              <PlayerChip
                key={
                  revealBeat?.winner === player.name
                    ? `${player.name}-pulse-${revealBeat.seq}`
                    : clarified
                      ? `${player.name}-clarify-${clarifyBeat?.seq}`
                      : locked
                        ? `${player.name}-lock-${lockBeat?.seq}`
                        : player.name
                }
                name={player.name}
                score={player.score}
                previousScore={prevScores.get(player.name) ?? player.score}
                streak={player.streak}
                leader={player.leader}
                clarify={clarified}
                locked={locked}
              />
            );
          })}
        </div>
        {questionLive && (
          <button
            type="button"
            onPointerDown={beginSkipHold}
            onPointerUp={cancelSkipHold}
            onPointerLeave={cancelSkipHold}
            onPointerCancel={cancelSkipHold}
            onKeyDown={(event) => {
              if ((event.key === 'Enter' || event.key === ' ') && !event.repeat) {
                event.preventDefault();
                beginSkipHold();
              }
            }}
            onKeyUp={(event) => {
              if (event.key === 'Enter' || event.key === ' ') cancelSkipHold();
            }}
            onContextMenu={(event) => event.preventDefault()}
            disabled={skipping}
            aria-label="Hold to skip this question"
            className={cn(
              'lily-pill-enter lily-skip pointer-events-auto relative flex min-h-[44px] shrink-0 touch-none select-none items-center gap-1.5 overflow-hidden rounded-full border border-[var(--border)] bg-transparent px-4 text-[11px] font-medium uppercase tracking-[0.16em] text-[var(--text-muted)] transition-colors hover:text-[var(--text)] disabled:opacity-40',
              holdingSkip && 'lily-skip-holding',
            )}
          >
            <SkipForward size={14} weight="light" aria-hidden />
            hold to skip
          </button>
        )}
      </div>
      {skipFailed && (
        <p
          className="mt-2 text-center text-xs text-[var(--lily-wrong)]"
          role="alert"
        >
          Lily didn’t catch that — hold to try again, or say “skip”.
        </p>
      )}
    </div>
  );
}

