1	'use client';
2	
3	/**
4	 * Lily state transport — LiveKit-native, no parallel channel.
5	 *
6	 * Three subscriptions, one typed GameState out (see the seam contract in
7	 * src/components/lily/state.ts):
8	 *   - agent participant attribute changes → layout state (LWW, snap-restores
9	 *     for late joiners straight from the current attribute values)
10	 *   - room metadata changes → question text + reveal payload
11	 *   - `lily.events` reliable data packets → exact-moment animation beats
12	 *
13	 * The reducer holds last state whenever updates pause or a payload fails to
14	 * parse. A failure watchdog degrades to "calm scoreboard" mode off the
15	 * `last_active_at` heartbeat's staleness — never off connectionQuality.
16	 * Staleness is measured on the local clock from the moment the heartbeat
17	 * value was last observed to change, so agent↔client clock skew cannot
18	 * produce false positives.
19	 */
20	
21	import { useCallback, useEffect, useRef, useState } from 'react';
22	import { ParticipantKind, RoomEvent, type Participant, type Room } from 'livekit-client';
23	import { ParticipantAgentAttributes } from '@livekit/components-core';
24	import {
25	  LILY_EVENTS_TOPIC,
26	  LILY_HEARTBEAT_STALE_MS,
27	  LILY_INITIAL_STATE,
28	  LILY_RPC_IMAGE_SHOWN,
29	  LILY_RPC_SKIP,
30	  LILY_RPC_START,
31	  parseLilyAnswerWindow,
32	  parseLilyEvent,
33	  parseLilyLastActiveAtMs,
34	  parseLilyMediaMode,
35	  parseLilyNextQuestionReady,
36	  parseLilyPacing,
37	  parseLilyMode,
38	  parseLilyPhase,
39	  parseLilyPlayers,
40	  parseLilyRoomMetadata,
41	  reduceLilyHistory,
42	  type LilyEvent,
43	  type LilyGameState,
44	  type LilyQuestionSnapshot,
45	} from '@/components/lily/state';
46	
47	/** The Lily agent participant: AGENT kind, not a publish-on-behalf shadow. */
48	export function isLilyAgentParticipant(participant: Participant): boolean {
49	  return (
50	    participant.kind === ParticipantKind.AGENT &&
51	    // Defensive `?? {}`: a participant surfacing without attributes made
52	    // the `in` check throw inside the mount effect / RPC path.
53	    !(ParticipantAgentAttributes.PublishOnBehalf in (participant.attributes ?? {}))
54	  );
55	}
56	
57	function findLilyAgent(room: Room): Participant | undefined {
58	  for (const participant of room.remoteParticipants.values()) {
59	    if (isLilyAgentParticipant(participant)) return participant;
60	  }
61	  return undefined;
62	}
63	
64	export function useLilyGameState(room: Room | undefined): {
65	  state: LilyGameState;
66	  /** Heartbeat watchdog: true ⇒ degrade to calm-scoreboard mode. */
67	  stale: boolean;
68	  /** Lily's agent participant is in the room right now. */
69	  agentPresent: boolean;
70	} {
71	  const [state, setState] = useState<LilyGameState>(LILY_INITIAL_STATE);
72	  const [stale, setStale] = useState(false);
73	  const [agentPresent, setAgentPresent] = useState(false);
74	  // Local-clock timestamp of the last observed heartbeat *change*.
75	  const lastHeartbeatSeenRef = useRef<{ value: number; seenAtMs: number } | null>(null);
76	  // Backward-compatible watchdog anchor for workers that have not adopted
77	  // last_active_at yet. Any clean agent attribute packet counts as activity.
78	  const fallbackActivitySeenAtRef = useRef<number | null>(null);
79	
80	  const applyAttributes = useCallback((participant: Participant) => {
81	    const attrs = participant.attributes ?? {};
82	
83	    const heartbeatMs = parseLilyLastActiveAtMs(attrs['last_active_at']);
84	    if (heartbeatMs !== null) {
85	      const previous = lastHeartbeatSeenRef.current;
86	      if (!previous || previous.value !== heartbeatMs) {
87	        lastHeartbeatSeenRef.current = { value: heartbeatMs, seenAtMs: Date.now() };
88	      }
89	    }
90	    // ANY clean agent attribute packet is proof of life — refresh the
91	    // activity anchor unconditionally. This branch previously ran only
92	    // when last_active_at was ABSENT; because LiveKit merges attributes
93	    // server-side, one heartbeat ever seen meant the anchor froze at that
94	    // arrival time unless the heartbeat VALUE advanced — a worker pushing
95	    // phase/players without bumping the heartbeat degraded a live board
96	    // to calm-scoreboard "· holding ·" mid-game.
97	    fallbackActivitySeenAtRef.current = Date.now();
98	    setStale(false);
99	
100	    setState((previous) => {
101	      const phase = parseLilyPhase(attrs['phase']);
102	      const mode = parseLilyMode(attrs['mode']);
103	      const mediaMode = parseLilyMediaMode(attrs['media_mode']);
104	      const pacing = parseLilyPacing(attrs['pacing']);
105	      const players = parseLilyPlayers(attrs['players']);
106	      const nextQuestionReady = parseLilyNextQuestionReady(attrs['next_question_ready']);
107	      const answerWindow = parseLilyAnswerWindow(attrs['answer_window']);
108	      const round = attrs['round'] !== undefined ? Number.parseInt(attrs['round'], 10) : NaN;
109	      const questionNumber =
110	        attrs['question_number'] !== undefined ? Number.parseInt(attrs['question_number'], 10) : NaN;
111	
112	      // Per-key merge: only keys that parsed cleanly overwrite; everything
113	      // else holds last state (missing/partial keys are expected mid-game).
114	      return {
115	        ...previous,
116	        phase: phase ?? previous.phase,
117	        mode: mode ?? previous.mode,
118	        // Sticky session flag — optional seam key; hold last when absent.
119	        mediaMode: mediaMode ?? previous.mediaMode,
120	        pacing: pacing ?? previous.pacing,
121	        players: players ?? previous.players,
122	        // Supply-stall flag — optional seam key; hold last when absent so a
123	        // partial attribute packet never clears an active hold.
124	        nextQuestionReady: nextQuestionReady ?? previous.nextQuestionReady,
125	        answerWindow: answerWindow ?? previous.answerWindow,
126	        round: Number.isFinite(round) ? round : previous.round,
127	        questionNumber: Number.isFinite(questionNumber) ? questionNumber : previous.questionNumber,
128	        lastActiveAtMs: heartbeatMs ?? previous.lastActiveAtMs,
129	      };
130	    });
131	  }, []);
132	
133	  const applyRoomMetadata = useCallback((metadata: string | undefined) => {
134	    const parsed = parseLilyRoomMetadata(metadata);
135	    if (!parsed) return;
136	    // The metadata singleton always carries current truth: a fresh question
137	    // arrives with reveal=null (clearing the previous reveal), the reveal
138	    // update carries both. Overwrite all fields together (image_url /
139	    // category / choices / eliminated are optional — absent means the plain
140	    // text-only question, so they clear with each update).
141	    setState((previous) => {
142	      // HOTFIX-005 X6: stale-render detector. The glass renders the same
143	      // agent-pushed projection as the spoken lane (no independent client
144	      // state), so a persistent gap between the question this metadata
145	      // projects and the active attribute question number is a stale render
146	      // — the operator narrating a previous question back while a new one
147	      // aired. Log it (both present, both differ) so the desync is readable.
148	      if (
149	        parsed.questionNumber !== null &&
150	        previous.questionNumber !== null &&
151	        parsed.questionNumber !== previous.questionNumber
152	      ) {
153	        console.warn(
154	          `[lily] stale-render: metadata question #${parsed.questionNumber} ` +
155	            `≠ active question #${previous.questionNumber}`,
156	        );
157	      }
158	      return {
159	        ...previous,
160	        question: parsed.question,
161	        imageUrl: parsed.imageUrl,
162	        category: parsed.category,
163	        choices: parsed.choices,
164	        eliminated: parsed.eliminated,
165	        reveal: parsed.reveal,
166	        wager: parsed.wager,
167	      };
168	    });
169	  }, []);
170	
171	  useEffect(() => {
172	    if (!room) return;
173	
174	    // Late-joiner snap-restore: attributes + metadata already hold current
175	    // truth on join — no event replay needed. setState-in-effect is
176	    // intentional: we're syncing UI state from an external subscription's
177	    // current snapshot (same pattern as Zuna's receipt listener).
178	    const existingAgent = findLilyAgent(room);
179	    // eslint-disable-next-line react-hooks/set-state-in-effect
180	    if (existingAgent) applyAttributes(existingAgent);
181	    applyRoomMetadata(room.metadata);
182	    setAgentPresent(!!existingAgent);
183	
184	    const onAttributesChanged = (_changed: Record<string, string>, participant: Participant) => {
185	      if (isLilyAgentParticipant(participant)) {
186	        applyAttributes(participant);
187	        // Presence race fix (live 2026-07-15): ParticipantConnected can
188	        // fire BEFORE the participant's kind resolves to AGENT, so the
189	        // connect handler misses her and nothing retries — the lobby hero
190	        // sat on "She's on her way…" while her attributes were already
191	        // flowing. Any agent-attribute write IS presence.
192	        setAgentPresent(true);
193	      }
194	    };
195	    const onParticipantConnected = (participant: Participant) => {
196	      if (isLilyAgentParticipant(participant)) {
197	        applyAttributes(participant);
198	        setAgentPresent(true);
199	      }
200	    };
201	    const onParticipantDisconnected = (participant: Participant) => {
202	      if (isLilyAgentParticipant(participant)) {
203	        setAgentPresent(!!findLilyAgent(room));
204	      }
205	    };
206	    const onRoomMetadataChanged = (metadata: string) => {
207	      applyRoomMetadata(metadata);
208	    };
209	    // Full-reconnect resync: after an ICE restart / network drop the
210	    // change events for anything that moved during the gap may never
211	    // replay — the board could hold a pre-drop question or reveal
212	    // indefinitely. Re-run the same snapshot the mount path uses.
213	    const onReconnected = () => {
214	      const agent = findLilyAgent(room);
215	      if (agent) applyAttributes(agent);
216	      applyRoomMetadata(room.metadata);
217	      setAgentPresent(!!agent);
218	    };
219	
220	    room.on(RoomEvent.ParticipantAttributesChanged, onAttributesChanged);
221	    room.on(RoomEvent.ParticipantConnected, onParticipantConnected);
222	    room.on(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
223	    room.on(RoomEvent.RoomMetadataChanged, onRoomMetadataChanged);
224	    room.on(RoomEvent.Reconnected, onReconnected);
225	    return () => {
226	      room.off(RoomEvent.ParticipantAttributesChanged, onAttributesChanged);
227	      room.off(RoomEvent.ParticipantConnected, onParticipantConnected);
228	      room.off(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
229	      room.off(RoomEvent.RoomMetadataChanged, onRoomMetadataChanged);
230	      room.off(RoomEvent.Reconnected, onReconnected);
231	    };
232	  }, [room, applyAttributes, applyRoomMetadata]);
233	
234	  // Heartbeat watchdog: check every 5s; stale once the heartbeat hasn't
235	  // advanced for LILY_HEARTBEAT_STALE_MS on the local clock.
236	  useEffect(() => {
237	    const timer = setInterval(() => {
238	      // Most recent proof of life wins — heartbeat change OR any clean
239	      // attribute packet (the fallback anchor now refreshes on every
240	      // packet, so it is the usual freshest signal).
241	      const heartbeatSeenAtMs = lastHeartbeatSeenRef.current?.seenAtMs ?? 0;
242	      const activitySeenAtMs = fallbackActivitySeenAtRef.current ?? 0;
243	      const seenAtMs = Math.max(heartbeatSeenAtMs, activitySeenAtMs);
244	      if (!seenAtMs) return; // no agent activity yet (pre-connect)
245	      setStale(Date.now() - seenAtMs > LILY_HEARTBEAT_STALE_MS);
246	    }, 5_000);
247	    return () => clearInterval(timer);
248	  }, []);
249	
250	  return { state, stale, agentPresent };
251	}
252	
253	/**
254	 * Read-only review buffer for back-navigation. Folds the live game state into
255	 * an append-only history of question snapshots (see reduceLilyHistory): each
256	 * distinct rendered question appends, a later reveal on the same question
257	 * folds in. Non-destructive by construction — it only OBSERVES `state`, never
258	 * writes it, so paging through history cannot rewind score/turn state. The
259	 * live reducer keeps advancing while a review overlay reads this buffer.
260	 */
261	export function useLilyHistory(state: LilyGameState): LilyQuestionSnapshot[] {
262	  const [history, setHistory] = useState<LilyQuestionSnapshot[]>([]);
263	  useEffect(() => {
264	    // Accumulating a persistent buffer from external-subscription-derived
265	    // state. reduceLilyHistory returns the SAME reference when nothing
266	    // changed, so this setter is a bail-out no-op on unrelated churn.
267	    setHistory((previous) => reduceLilyHistory(previous, state));
268	    // Deps are the question-shaping fields ONLY (intentional): re-running on
269	    // every `state` identity change (players/answerWindow/heartbeat) would
270	    // recompute the buffer needlessly. reduceLilyHistory reads only these.
271	    // eslint-disable-next-line react-hooks/exhaustive-deps
272	  }, [
273	    state.question,
274	    state.questionNumber,
275	    state.round,
276	    state.imageUrl,
277	    state.category,
278	    state.choices,
279	    state.eliminated,
280	    state.reveal,
281	  ]);
282	  return history;
283	}
284	
285	/**
286	 * Subscribe to `lily.events` reliable data packets. All animations fire off
287	 * these beats (bind / reveal / callout / finale), never off attribute
288	 * propagation, to hold the visual-lag rule.
289	 */
290	export function useLilyEvents(room: Room | undefined, onEvent: (event: LilyEvent) => void): void {
291	  const handlerRef = useRef(onEvent);
292	  useEffect(() => {
293	    handlerRef.current = onEvent;
294	  }, [onEvent]);
295	
296	  useEffect(() => {
297	    if (!room) return;
298	
299	    const onDataReceived = (
300	      payload: Uint8Array,
301	      _participant?: Participant,
302	      _kind?: unknown,
303	      topic?: string,
304	    ) => {
305	      if (topic !== LILY_EVENTS_TOPIC) return;
306	      const event = parseLilyEvent(payload);
307	      if (event) handlerRef.current(event);
308	    };
309	
310	    room.on(RoomEvent.DataReceived, onDataReceived);
311	    return () => {
312	      room.off(RoomEvent.DataReceived, onDataReceived);
313	    };
314	  }, [room]);
315	}
316	
317	/**
318	 * The surface's ONLY two interactive calls: RPCs to the agent participant.
319	 * Everything else on screen is a pure render of agent-pushed state.
320	 */
321	export function useLilyControls(room: Room | undefined): {
322	  start: () => Promise<boolean>;
323	  skip: () => Promise<boolean>;
324	  imageShown: (url: string) => void;
325	} {
326	  const perform = useCallback(
327	    async (
328	      method: typeof LILY_RPC_START | typeof LILY_RPC_SKIP,
329	      payload: Record<string, unknown> = { source: 'lily_surface' },
330	    ): Promise<boolean> => {
331	      if (!room) return false;
332	      const agent = findLilyAgent(room);
333	      if (!agent) return false;
334	      try {
335	        await room.localParticipant.performRpc({
336	          destinationIdentity: agent.identity,
337	          method,
338	          payload: JSON.stringify(payload),
339	        });
340	        return true;
341	      } catch (err) {
342	        console.warn(`[lily] rpc ${method} failed:`, err);
343	        return false;
344	      }
345	    },
346	    [room],
347	  );
348	
349	  const start = useCallback(() => perform(LILY_RPC_START), [perform]);
