'use client';

/**
 * Lily state transport — LiveKit-native, no parallel channel.
 *
 * Three subscriptions, one typed GameState out (see the seam contract in
 * src/components/lily/state.ts):
 *   - agent participant attribute changes → layout state (LWW, snap-restores
 *     for late joiners straight from the current attribute values)
 *   - room metadata changes → question text + reveal payload
 *   - `lily.events` reliable data packets → exact-moment animation beats
 *
 * The reducer holds last state whenever updates pause or a payload fails to
 * parse. A failure watchdog degrades to "calm scoreboard" mode off the
 * `last_active_at` heartbeat's staleness — never off connectionQuality.
 * Staleness is measured on the local clock from the moment the heartbeat
 * value was last observed to change, so agent↔client clock skew cannot
 * produce false positives.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { ParticipantKind, RoomEvent, type Participant, type Room } from 'livekit-client';
import { ParticipantAgentAttributes } from '@livekit/components-core';
import {
  LILY_EVENTS_TOPIC,
  LILY_HEARTBEAT_STALE_MS,
  LILY_INITIAL_STATE,
  LILY_RPC_IMAGE_SHOWN,
  LILY_RPC_SKIP,
  LILY_RPC_START,
  parseLilyAnswerWindow,
  parseLilyEvent,
  parseLilyLastActiveAtMs,
  parseLilyMediaMode,
  parseLilyNextQuestionReady,
  parseLilyPacing,
  parseLilyMode,
  parseLilyPhase,
  parseLilyPlayers,
  parseLilyRoomMetadata,
  reduceLilyHistory,
  type LilyEvent,
  type LilyGameState,
  type LilyQuestionSnapshot,
} from '@/components/lily/state';

/** The Lily agent participant: AGENT kind, not a publish-on-behalf shadow. */
export function isLilyAgentParticipant(participant: Participant): boolean {
  return (
    participant.kind === ParticipantKind.AGENT &&
    // Defensive `?? {}`: a participant surfacing without attributes made
    // the `in` check throw inside the mount effect / RPC path.
    !(ParticipantAgentAttributes.PublishOnBehalf in (participant.attributes ?? {}))
  );
}

function findLilyAgent(room: Room): Participant | undefined {
  for (const participant of room.remoteParticipants.values()) {
    if (isLilyAgentParticipant(participant)) return participant;
  }
  return undefined;
}

export function useLilyGameState(room: Room | undefined): {
  state: LilyGameState;
  /** Heartbeat watchdog: true ⇒ degrade to calm-scoreboard mode. */
  stale: boolean;
  /** Lily's agent participant is in the room right now. */
  agentPresent: boolean;
} {
  const [state, setState] = useState<LilyGameState>(LILY_INITIAL_STATE);
  const [stale, setStale] = useState(false);
  const [agentPresent, setAgentPresent] = useState(false);
  // Local-clock timestamp of the last observed heartbeat *change*.
  const lastHeartbeatSeenRef = useRef<{ value: number; seenAtMs: number } | null>(null);
  // Backward-compatible watchdog anchor for workers that have not adopted
  // last_active_at yet. Any clean agent attribute packet counts as activity.
  const fallbackActivitySeenAtRef = useRef<number | null>(null);

  const applyAttributes = useCallback((participant: Participant) => {
    const attrs = participant.attributes ?? {};

    const heartbeatMs = parseLilyLastActiveAtMs(attrs['last_active_at']);
    if (heartbeatMs !== null) {
      const previous = lastHeartbeatSeenRef.current;
      if (!previous || previous.value !== heartbeatMs) {
        lastHeartbeatSeenRef.current = { value: heartbeatMs, seenAtMs: Date.now() };
      }
    }
    // ANY clean agent attribute packet is proof of life — refresh the
    // activity anchor unconditionally. This branch previously ran only
    // when last_active_at was ABSENT; because LiveKit merges attributes
    // server-side, one heartbeat ever seen meant the anchor froze at that
    // arrival time unless the heartbeat VALUE advanced — a worker pushing
    // phase/players without bumping the heartbeat degraded a live board
    // to calm-scoreboard "· holding ·" mid-game.
    fallbackActivitySeenAtRef.current = Date.now();
    setStale(false);

    setState((previous) => {
      const phase = parseLilyPhase(attrs['phase']);
      const mode = parseLilyMode(attrs['mode']);
      const mediaMode = parseLilyMediaMode(attrs['media_mode']);
      const pacing = parseLilyPacing(attrs['pacing']);
      const players = parseLilyPlayers(attrs['players']);
      const nextQuestionReady = parseLilyNextQuestionReady(attrs['next_question_ready']);
      const answerWindow = parseLilyAnswerWindow(attrs['answer_window']);
      const round = attrs['round'] !== undefined ? Number.parseInt(attrs['round'], 10) : NaN;
      const questionNumber =
        attrs['question_number'] !== undefined ? Number.parseInt(attrs['question_number'], 10) : NaN;

      // Per-key merge: only keys that parsed cleanly overwrite; everything
      // else holds last state (missing/partial keys are expected mid-game).
      return {
        ...previous,
        phase: phase ?? previous.phase,
        mode: mode ?? previous.mode,
        // Sticky session flag — optional seam key; hold last when absent.
        mediaMode: mediaMode ?? previous.mediaMode,
        pacing: pacing ?? previous.pacing,
        players: players ?? previous.players,
        // Supply-stall flag — optional seam key; hold last when absent so a
        // partial attribute packet never clears an active hold.
        nextQuestionReady: nextQuestionReady ?? previous.nextQuestionReady,
        answerWindow: answerWindow ?? previous.answerWindow,
        round: Number.isFinite(round) ? round : previous.round,
        questionNumber: Number.isFinite(questionNumber) ? questionNumber : previous.questionNumber,
        lastActiveAtMs: heartbeatMs ?? previous.lastActiveAtMs,
      };
    });
  }, []);

  const applyRoomMetadata = useCallback((metadata: string | undefined) => {
    const parsed = parseLilyRoomMetadata(metadata);
    if (!parsed) return;
    // The metadata singleton always carries current truth: a fresh question
    // arrives with reveal=null (clearing the previous reveal), the reveal
    // update carries both. Overwrite all fields together (image_url /
    // category / choices / eliminated are optional — absent means the plain
    // text-only question, so they clear with each update).
    setState((previous) => {
      // HOTFIX-005 X6: stale-render detector. The glass renders the same
      // agent-pushed projection as the spoken lane (no independent client
      // state), so a persistent gap between the question this metadata
      // projects and the active attribute question number is a stale render
      // — the operator narrating a previous question back while a new one
      // aired. Log it (both present, both differ) so the desync is readable.
      if (
        parsed.questionNumber !== null &&
        previous.questionNumber !== null &&
        parsed.questionNumber !== previous.questionNumber
      ) {
        console.warn(
          `[lily] stale-render: metadata question #${parsed.questionNumber} ` +
            `≠ active question #${previous.questionNumber}`,
        );
      }
      return {
        ...previous,
        question: parsed.question,
        imageUrl: parsed.imageUrl,
        category: parsed.category,
        choices: parsed.choices,
        eliminated: parsed.eliminated,
        reveal: parsed.reveal,
        wager: parsed.wager,
      };
    });
  }, []);

  useEffect(() => {
    if (!room) return;

    // Late-joiner snap-restore: attributes + metadata already hold current
    // truth on join — no event replay needed. setState-in-effect is
    // intentional: we're syncing UI state from an external subscription's
    // current snapshot (same pattern as Zuna's receipt listener).
    const existingAgent = findLilyAgent(room);
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (existingAgent) applyAttributes(existingAgent);
    applyRoomMetadata(room.metadata);
    setAgentPresent(!!existingAgent);

    const onAttributesChanged = (_changed: Record<string, string>, participant: Participant) => {
      if (isLilyAgentParticipant(participant)) {
        applyAttributes(participant);
        // Presence race fix (live 2026-07-15): ParticipantConnected can
        // fire BEFORE the participant's kind resolves to AGENT, so the
        // connect handler misses her and nothing retries — the lobby hero
        // sat on "She's on her way…" while her attributes were already
        // flowing. Any agent-attribute write IS presence.
        setAgentPresent(true);
      }
    };
    const onParticipantConnected = (participant: Participant) => {
      if (isLilyAgentParticipant(participant)) {
        applyAttributes(participant);
        setAgentPresent(true);
      }
    };
    const onParticipantDisconnected = (participant: Participant) => {
      if (isLilyAgentParticipant(participant)) {
        setAgentPresent(!!findLilyAgent(room));
      }
    };
    const onRoomMetadataChanged = (metadata: string) => {
      applyRoomMetadata(metadata);
    };
    // Full-reconnect resync: after an ICE restart / network drop the
    // change events for anything that moved during the gap may never
    // replay — the board could hold a pre-drop question or reveal
    // indefinitely. Re-run the same snapshot the mount path uses.
    const onReconnected = () => {
      const agent = findLilyAgent(room);
      if (agent) applyAttributes(agent);
      applyRoomMetadata(room.metadata);
      setAgentPresent(!!agent);
    };

    room.on(RoomEvent.ParticipantAttributesChanged, onAttributesChanged);
    room.on(RoomEvent.ParticipantConnected, onParticipantConnected);
    room.on(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
    room.on(RoomEvent.RoomMetadataChanged, onRoomMetadataChanged);
    room.on(RoomEvent.Reconnected, onReconnected);
    return () => {
      room.off(RoomEvent.ParticipantAttributesChanged, onAttributesChanged);
      room.off(RoomEvent.ParticipantConnected, onParticipantConnected);
      room.off(RoomEvent.ParticipantDisconnected, onParticipantDisconnected);
      room.off(RoomEvent.RoomMetadataChanged, onRoomMetadataChanged);
      room.off(RoomEvent.Reconnected, onReconnected);
    };
  }, [room, applyAttributes, applyRoomMetadata]);

  // Heartbeat watchdog: check every 5s; stale once the heartbeat hasn't
  // advanced for LILY_HEARTBEAT_STALE_MS on the local clock.
  useEffect(() => {
    const timer = setInterval(() => {
      // Most recent proof of life wins — heartbeat change OR any clean
      // attribute packet (the fallback anchor now refreshes on every
      // packet, so it is the usual freshest signal).
      const heartbeatSeenAtMs = lastHeartbeatSeenRef.current?.seenAtMs ?? 0;
      const activitySeenAtMs = fallbackActivitySeenAtRef.current ?? 0;
      const seenAtMs = Math.max(heartbeatSeenAtMs, activitySeenAtMs);
      if (!seenAtMs) return; // no agent activity yet (pre-connect)
      setStale(Date.now() - seenAtMs > LILY_HEARTBEAT_STALE_MS);
    }, 5_000);
    return () => clearInterval(timer);
  }, []);

  return { state, stale, agentPresent };
}

/**
 * Read-only review buffer for back-navigation. Folds the live game state into
 * an append-only history of question snapshots (see reduceLilyHistory): each
 * distinct rendered question appends, a later reveal on the same question
 * folds in. Non-destructive by construction — it only OBSERVES `state`, never
 * writes it, so paging through history cannot rewind score/turn state. The
 * live reducer keeps advancing while a review overlay reads this buffer.
 */
export function useLilyHistory(state: LilyGameState): LilyQuestionSnapshot[] {
  const [history, setHistory] = useState<LilyQuestionSnapshot[]>([]);
  useEffect(() => {
    // Accumulating a persistent buffer from external-subscription-derived
    // state. reduceLilyHistory returns the SAME reference when nothing
    // changed, so this setter is a bail-out no-op on unrelated churn.
    setHistory((previous) => reduceLilyHistory(previous, state));
    // Deps are the question-shaping fields ONLY (intentional): re-running on
    // every `state` identity change (players/answerWindow/heartbeat) would
    // recompute the buffer needlessly. reduceLilyHistory reads only these.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    state.question,
    state.questionNumber,
    state.round,
    state.imageUrl,
    state.category,
    state.choices,
    state.eliminated,
    state.reveal,
  ]);
  return history;
}

/**
 * Subscribe to `lily.events` reliable data packets. All animations fire off
 * these beats (bind / reveal / callout / finale), never off attribute
 * propagation, to hold the visual-lag rule.
 */
export function useLilyEvents(room: Room | undefined, onEvent: (event: LilyEvent) => void): void {
  const handlerRef = useRef(onEvent);
  useEffect(() => {
    handlerRef.current = onEvent;
  }, [onEvent]);

  useEffect(() => {
    if (!room) return;

    const onDataReceived = (
      payload: Uint8Array,
      _participant?: Participant,
      _kind?: unknown,
      topic?: string,
    ) => {
      if (topic !== LILY_EVENTS_TOPIC) return;
      const event = parseLilyEvent(payload);
      if (event) handlerRef.current(event);
    };

    room.on(RoomEvent.DataReceived, onDataReceived);
    return () => {
      room.off(RoomEvent.DataReceived, onDataReceived);
    };
  }, [room]);
}

/**
 * The surface's ONLY two interactive calls: RPCs to the agent participant.
 * Everything else on screen is a pure render of agent-pushed state.
 */
export function useLilyControls(room: Room | undefined): {
  start: () => Promise<boolean>;
  skip: () => Promise<boolean>;
  imageShown: (url: string) => void;
} {
  const perform = useCallback(
    async (
      method: typeof LILY_RPC_START | typeof LILY_RPC_SKIP,
      payload: Record<string, unknown> = { source: 'lily_surface' },
    ): Promise<boolean> => {
      if (!room) return false;
      const agent = findLilyAgent(room);
      if (!agent) return false;
      try {
        await room.localParticipant.performRpc({
          destinationIdentity: agent.identity,
          method,
          payload: JSON.stringify(payload),
        });
        return true;
      } catch (err) {
        console.warn(`[lily] rpc ${method} failed:`, err);
        return false;
      }
    },
    [room],
  );

  const start = useCallback(() => perform(LILY_RPC_START), [perform]);
  const skip = useCallback(() => perform(LILY_RPC_SKIP), [perform]);

  // HOTFIX-005 X4: render confirmation. Fire-and-forget, de-duped per URL so
  // a re-mount / re-load doesn't spam the agent — the agent only needs to
  // know THAT this image reached the glass. Best-effort: a failed confirm
  // just leaves the state unconfirmed (the agent hedges its picture claim),
  // never blocks the render.
  const lastShownRef = useRef<string | null>(null);
  const imageShown = useCallback(
    (url: string) => {
      if (!url || lastShownRef.current === url) return;
      lastShownRef.current = url;
      // Not awaited: rendering must never wait on the round-trip.
      void room?.localParticipant
        .performRpc({
          destinationIdentity: findLilyAgent(room)?.identity ?? '',
          method: LILY_RPC_IMAGE_SHOWN,
          payload: JSON.stringify({ url }),
        })
        .catch((err) => console.warn('[lily] rpc image_shown failed:', err));
    },
    [room],
  );

  return { start, skip, imageShown };
}

    if output_audio_options:
        self._audio_output = _ParticipantAudioOutput(
            self._room,
            sample_rate=output_audio_options.sample_rate,
            num_channels=output_audio_options.num_channels,
            track_publish_options=output_audio_options.track_publish_options,
            track_name=(
                output_audio_options.track_name
                if utils.is_given(output_audio_options.track_name)
                else "roomio_audio"
            ),
        )

    output_text_options = self._options.get_text_output_options()
    if output_text_options:
        self._user_tr_output = _ParticipantTranscriptionOutput(
            room=self._room, is_delta_stream=False, participant=self._participant_identity
        )
        self._user_transcript_ch = utils.aio.Chan[UserInputTranscribedEvent]()
        self._user_transcript_atask = asyncio.create_task(
            self._forward_user_transcript(self._user_transcript_ch)
        )

        self._agent_tr_output = _ParticipantTranscriptionOutput(
            room=self._room,
            is_delta_stream=True,
            participant=None,
            next_in_chain=output_text_options.next_in_chain,
            json_format=output_text_options.json_format,
        )

        # use the RoomIO's audio output if available, otherwise use the agent's audio output
        # (e.g the audio output isn't using RoomIO with our avatar datastream impl)
        if output_text_options.sync_transcription is not False and (
            audio_output := self._audio_output or self._agent_session.output.audio
        ):
            self._tr_synchronizer = TranscriptSynchronizer(
                next_in_chain_audio=audio_output,
                next_in_chain_text=self._agent_tr_output,
                speed=output_text_options.transcription_speed_factor,
            )

    # -- set the room event handlers --
    self._room.on("participant_connected", self._on_participant_connected)
    self._room.on("connection_state_changed", self._on_connection_state_changed)
    self._room.on("participant_disconnected", self._on_participant_disconnected)
