1	'use client';
2	
3	/**
4	 * Terminal — final standings with the winner promoted to a display-scale
5	 * hero (crown + Fraunces name + numeral: no all-whisper screens on this
6	 * surface), biggest-comeback / best-wrong-answer callouts (accumulated off
7	 * `callout` beats; rendered only if the agent sent them), and the fleet
8	 * terminal actions: "Play Again" via restartAgentSession() and the shared
9	 * SessionExport for the transcript.
10	 */
11	
12	import { useRouter } from 'next/navigation';
13	import { useSessionContext, useSessionMessages } from '@livekit/components-react';
14	import { ArrowCounterClockwise, Crown } from '@phosphor-icons/react';
15	import { restartAgentSession } from '@/lib/session-restart';
16	import { SessionExport } from '@/components/agents-ui/session-export';
17	import type { LilyCallout, LilyGameState } from '@/components/lily/state';
18	
19	const LILY_START_PATH = '/lily';
20	
21	function calloutLabel(calloutType: string): string {
22	  const known: Record<string, string> = {
23	    biggest_comeback: 'Biggest comeback',
24	    best_wrong_answer: 'Best wrong answer',
25	  };
26	  return known[calloutType] ?? calloutType.replace(/[_-]+/g, ' ');
27	}
28	
29	export function LilyTerminal({
30	  state,
31	  callouts,
32	}: {
33	  state: LilyGameState;
34	  callouts: LilyCallout[];
35	}) {
36	  const router = useRouter();
37	  const session = useSessionContext();
38	  const { messages } = useSessionMessages(session);
39	
40	  // Presentation-only ordering of the agent's committed scores. Determinstic
41	  // tiebreak (agent's leader flag, then name) so tied rows can't reshuffle
42	  // between renders or contradict the crowned chip.
43	  const standings = [...state.players].sort(
44	    (a, b) =>
45	      b.score - a.score ||
46	      Number(b.leader) - Number(a.leader) ||
47	      a.name.localeCompare(b.name),
48	  );
49	  const topScore = standings[0]?.score ?? 0;
50	  // A tied top score crowns ALL of its holders — the hero used to declare
51	  // whichever tied player happened to sort first the sole winner.
52	  const winners = standings.filter((player) => player.score === topScore);
53	  const isTie = winners.length > 1;
54	  const rest = standings.slice(winners.length);
55	  const nobodyScored =
56	    standings.length === 0 || (topScore === 0 && winners.length === standings.length);
57	  const winner = nobodyScored ? undefined : winners[0];
58	  const winnerNames = winners.map((player) => player.name).join(' & ');
59	
60	  return (
61	    <div className="lily-centerline pointer-events-auto flex h-full w-full flex-col items-center justify-center gap-7 overflow-y-auto px-6 py-6 text-center">
62	      <div className="flex items-center justify-center gap-3">
63	        <p className="lily-eyebrow text-[13px]">final standings</p>
64	        {state.mode === 'adult' && (
65	          // Contrast guard: accent hairline, cream text at this size.
66	          <span className="inline-block rounded-full border border-[var(--lily-accent)] px-2.5 py-0.5 text-[11px] font-semibold tracking-[0.08em] text-[var(--text)]">
67	            18+
68	          </span>
69	        )}
70	      </div>
