'use client';

/**
 * Terminal — final standings with the winner promoted to a display-scale
 * hero (crown + Fraunces name + numeral: no all-whisper screens on this
 * surface), biggest-comeback / best-wrong-answer callouts (accumulated off
 * `callout` beats; rendered only if the agent sent them), and the fleet
 * terminal actions: "Play Again" via restartAgentSession() and the shared
 * SessionExport for the transcript.
 */

import { useRouter } from 'next/navigation';
import { useSessionContext, useSessionMessages } from '@livekit/components-react';
import { ArrowCounterClockwise, Crown } from '@phosphor-icons/react';
import { restartAgentSession } from '@/lib/session-restart';
import { SessionExport } from '@/components/agents-ui/session-export';
import type { LilyCallout, LilyGameState } from '@/components/lily/state';

const LILY_START_PATH = '/lily';

function calloutLabel(calloutType: string): string {
  const known: Record<string, string> = {
    biggest_comeback: 'Biggest comeback',
    best_wrong_answer: 'Best wrong answer',
  };
  return known[calloutType] ?? calloutType.replace(/[_-]+/g, ' ');
}

export function LilyTerminal({
  state,
  callouts,
}: {
  state: LilyGameState;
  callouts: LilyCallout[];
}) {
  const router = useRouter();
  const session = useSessionContext();
  const { messages } = useSessionMessages(session);

  // Presentation-only ordering of the agent's committed scores. Determinstic
  // tiebreak (agent's leader flag, then name) so tied rows can't reshuffle
  // between renders or contradict the crowned chip.
  const standings = [...state.players].sort(
    (a, b) =>
      b.score - a.score ||
      Number(b.leader) - Number(a.leader) ||
      a.name.localeCompare(b.name),
  );
  const topScore = standings[0]?.score ?? 0;
  // A tied top score crowns ALL of its holders — the hero used to declare
  // whichever tied player happened to sort first the sole winner.
  const winners = standings.filter((player) => player.score === topScore);
  const isTie = winners.length > 1;
  const rest = standings.slice(winners.length);
  const nobodyScored =
    standings.length === 0 || (topScore === 0 && winners.length === standings.length);
  const winner = nobodyScored ? undefined : winners[0];
  const winnerNames = winners.map((player) => player.name).join(' & ');

  return (
    <div className="lily-centerline pointer-events-auto flex h-full w-full flex-col items-center justify-center gap-7 overflow-y-auto px-6 py-6 text-center">
      <div className="flex items-center justify-center gap-3">
        <p className="lily-eyebrow text-[13px]">final standings</p>
        {state.mode === 'adult' && (
          // Contrast guard: accent hairline, cream text at this size.
          <span className="inline-block rounded-full border border-[var(--lily-accent)] px-2.5 py-0.5 text-[11px] font-semibold tracking-[0.08em] text-[var(--text)]">
            18+
          </span>
        )}
      </div>

      {!winner ? (
        <p className="text-sm text-[var(--text-muted)]">No scores landed this time.</p>
      ) : (
        <>
          {/* Winner hero — the night's headline in display type. A tie
              promotes every co-champion into the hero together. */}
          <div className="lily-question-enter flex flex-col items-center gap-1">
            <Crown
              size={30}
              weight="light"
              aria-label={isTie ? 'Co-champions' : 'Winner'}
              className="text-[var(--lily-accent)]"
            />
            <p
              className="lily-display max-w-[22ch] leading-[1.05] text-balance text-[var(--text)]"
              style={{
                fontSize: isTie
                  ? 'clamp(1.8rem, 4.2vw + 0.7rem, 3.25rem)'
                  : 'clamp(2.4rem, 6vw + 0.8rem, 4.25rem)',
              }}
            >
              {winnerNames}
            </p>
            {isTie && (
              <p className="lily-eyebrow text-[11px]">co-champions</p>
            )}
            <p
              className="lily-display tabular-nums leading-none text-[var(--lily-accent)]"
              style={{ fontSize: 'clamp(1.9rem, 4.5vw + 0.6rem, 3.25rem)' }}
            >
              {winner.score}
            </p>
          </div>

          {rest.length > 0 && (
            <ol className="w-full max-w-[24rem] space-y-2">
              {rest.map((player, index) => (
                <li
                  key={player.name}
                  className="flex items-center justify-between gap-3 rounded-xl border border-[var(--border)] bg-[var(--surface)]/70 px-4 py-3"
                >
                  <span className="flex items-center gap-2 text-left">
                    <span className="lily-display tabular-nums w-5 text-base text-[var(--text-muted)]">
                      {index + winners.length + 1}
                    </span>
                    <span className="truncate text-sm font-medium text-[var(--text)]">{player.name}</span>
                  </span>
                  <span className="lily-display tabular-nums text-lg text-[var(--lily-accent)]">
                    {player.score}
                  </span>
                </li>
              ))}
            </ol>
          )}
        </>
      )}

      {callouts.length > 0 && (
        <div className="w-full max-w-[24rem] space-y-2">
          {callouts.map((callout, index) => (
            <div
              key={`${callout.calloutType}-${callout.name}-${index}`}
              className="rounded-xl border border-[var(--border)] bg-[var(--surface)]/60 px-4 py-3 text-left"
            >
              {/* Contrast guard: 10px labels sit in the muted token, not accent. */}
              <p className="text-[10px] font-medium uppercase tracking-[0.22em] text-[var(--text-muted)]">
                {calloutLabel(callout.calloutType)}
              </p>
              <p className="mt-1 text-sm text-[var(--text)]">
                <span className="font-semibold">{callout.name}</span>
                {callout.text && <span className="text-[var(--text-muted)]"> — {callout.text}</span>}
              </p>
            </div>
          ))}
        </div>
      )}

      <div className="flex flex-col items-center gap-4">
        <button
          type="button"
          onClick={() => restartAgentSession(router, LILY_START_PATH)}
          className="flex min-h-[52px] items-center justify-center gap-2.5 rounded-full border border-[var(--lily-accent)] bg-transparent px-9 text-sm font-semibold uppercase tracking-[0.14em] text-[var(--text)] btn-interactive"
        >
          <ArrowCounterClockwise size={18} weight="light" aria-hidden />
          Play Again
        </button>
        <SessionExport messages={messages} agentName="Lily" variant="post-session" />
      </div>
    </div>
  );
}

