// LiveKit transcription stream attributes (PRMPT Surface Channel Contract §2.2).
const SEGMENT_ID_ATTR = 'lk.segment_id';
const TRANSCRIPTION_FINAL_ATTR = 'lk.transcription_final';
const TRANSCRIBED_TRACK_ID_ATTR = 'lk.transcribed_track_id';

// Legacy lifecycle pills ride the lk.chat rail with this attribute set; they
// are status chrome, not conversation, and must be excluded from the
// transcript (mirrors the existing session view's filter). Declared locally —
// the shared strip module is intentionally not imported here.
const LIFECYCLE_MESSAGE_KIND_ATTR = 'prmpt.message_kind';

export type JrvsTextMessage = {
  id: string;
  role: 'agent' | 'user';
  inputMode: 'typed' | 'spoken';
  text: string;
  final: boolean;
  timestamp: number;
  synced: boolean;
  /**
   * Which rail delivered the message. 'transcription' = lk.transcription
   * (conversational output / STT captions); 'chat' = lk.chat (typed composer
   * input, plus grandfathered agent deliveries like media links and receipts).
   */
  via: 'chat' | 'transcription';
  /**
   * Parsed `doc_receipt` envelope (agent-side upload confirmation, mjrvs_agent
   * WO-JRVS-DOCRECEIPT-001) when this chat message was a typed control envelope.
   * When set, the raw JSON is swallowed (`text` is empty) and the transcript
   * renders a compact receipt chip instead of a chat bubble.
   */
  docReceipt?: DocReceipt;
};

/**
 * Pure discriminator for a transcription segment (contract §2.2/§2.3):
 * - `lk.transcribed_track_id` present → audio-synced caption; absent →
 *   text-only agent output (rendered instantly).
 * - `lk.transcription_final === 'true'` → final; otherwise interim.
 * - local participant → user 'spoken' (STT caption); non-local → agent.
 */
export function discriminateTranscription(
  attrs: Record<string, string> | undefined,
  isLocal: boolean,
): { synced: boolean; final: boolean; role: 'agent' | 'user'; inputMode: 'typed' | 'spoken' } {
  const synced = attrs?.[TRANSCRIBED_TRACK_ID_ATTR] !== undefined;
