/**
 * WO-LILY-UI-SYNC-TYPEWRITER-001: voice-synced question reveal.
 *
 * The agent (LILY_VOICE_SYNCED_TRANSCRIPT on) lets the framework's transcript
 * synchronizer release Lily's spoken words onto `lk.transcription` in step
 * with her audio playout. This hook reports how many words of the CURRENT
 * question's DELIVERY have been voiced so far, so the board can type the
 * question (whose clean text still comes from room metadata) to her cadence
 * instead of a fixed cosmetic stagger.
 *
 * Only Lily's own spoken (AGENT) segments count — the table's captions (which
 * Lily publishes impersonating the device participant) carry the local
 * identity and are excluded. The delivery segment is locked per question so a
 * later same-question nudge can't hijack or rewind the reveal. When no live
 * delivery segment is present (feature off, late join, banter), `active` is
 * false and the board falls back to its own entrance animation.
 */
export function useLilyDeliveryReveal(
  room: Room | undefined,
  state: LilyGameState,
): { questionNumber: number | null; wordCount: number; active: boolean } {
  const transcriptions = useTranscriptions();
  const { localParticipant } = useLocalParticipant();
  const localIdentity = localParticipant?.identity;

  const agentIdentity = useMemo(() => {
    if (!room) return undefined;
    for (const participant of room.remoteParticipants.values()) {
      if (isLilyAgentParticipant(participant)) return participant.identity;
    }
    return undefined;
  }, [room, transcriptions]);

  const lockRef = useRef<{ q: number | null; segId: string | null }>({ q: null, segId: null });

  return useMemo(() => {
    const q = state.questionNumber;
    if (q === null) return { questionNumber: null, wordCount: 0, active: false };

    // New question ⇒ drop the previous delivery lock.
    if (lockRef.current.q !== q) lockRef.current = { q, segId: null };

    const agentSegs = transcriptions.filter((segment) =>
      agentIdentity
        ? segment.participantInfo?.identity === agentIdentity
        : segment.participantInfo?.identity !== localIdentity,
    );

    const segIdOf = (segment: (typeof agentSegs)[number]): string =>
      segment.streamInfo?.attributes?.[ParticipantAgentAttributes.TranscriptionSegmentId] ??
      segment.streamInfo?.id ??
      '';

    // Metadata for a question lands at TTS playout start, so the delivery
    // segment is already airing when the question goes live — lock the newest
    // agent segment that has begun speaking while the question is un-revealed.
    const live = state.phase === 'question' || state.phase === 'answering';
    if (live && state.reveal === null && lockRef.current.segId === null) {
      for (let i = agentSegs.length - 1; i >= 0; i -= 1) {
        if ((agentSegs[i].text ?? '').trim().length > 0) {
          lockRef.current.segId = segIdOf(agentSegs[i]);
          break;
        }
      }
    }

    const segId = lockRef.current.segId;
    const seg = segId ? agentSegs.find((segment) => segIdOf(segment) === segId) : undefined;
    const wordCount = seg ? (seg.text ?? '').trim().split(/\s+/).filter(Boolean).length : 0;
    return { questionNumber: q, wordCount, active: !!seg };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [transcriptions, agentIdentity, localIdentity, state.questionNumber, state.phase, state.reveal]);
}
