/**
 * Chalk-write entrance: the question lands word by word (~40ms/word stagger,
 * each word a quick opacity + 2px rise). Re-keyed per question by the
 * caller. Reduced motion → the container does a single opacity swap and the
 * words render static (globals.css).
 */
function LilyChalkText({
  text,
  className,
  style,
}: {
  text: string;
  className?: string;
  style?: React.CSSProperties;
}) {
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <p className={cn('lily-chalk lily-question-text', className)} style={style}>
      {words.map((word, index) => (
        <Fragment key={`${index}-${word}`}>
          <span className="lily-word" style={{ animationDelay: `${index * 40}ms` }}>
            {word}
          </span>
          {index < words.length - 1 ? ' ' : null}
        </Fragment>
      ))}
    </p>
  );
}

