/**
 * Chalk-write entrance for the question.
 *
 * WO-LILY-UI-SYNC-TYPEWRITER-001: when `revealCount` is a number, the words
 * are driven by Lily's VOICE — the agent's transcript synchronizer releases
 * her spoken words onto lk.transcription in step with audio playout, and the
 * board reveals the question one word at a time to that cadence (word `index`
 * shows once `index < revealCount`). Words hold their layout (hidden = opacity
 * 0, present) so the centered question never reflows as it types. When the
 * segment completes it has voiced at least the whole question, so every word
 * lands.
 *
 * When `revealCount` is null/undefined the legacy entrance runs: a fixed
 * ~40ms/word cosmetic stagger (late join, feature off, or before the delivery
 * segment is airing). Reduced motion → single opacity swap, words static
 * (globals.css) in the legacy path; instant, no transition in the voiced path.
 */
function LilyChalkText({
  text,
  className,
  style,
  revealCount,
}: {
  text: string;
  className?: string;
  style?: React.CSSProperties;
  /** Voice-synced reveal: number of words voiced so far. null ⇒ legacy stagger. */
  revealCount?: number | null;
}) {
  const words = text.split(/\s+/).filter(Boolean);
  const voiced = typeof revealCount === 'number';
  const reduce = voiced && prefersReducedMotion();
  return (
    <p className={cn('lily-chalk lily-question-text', className)} style={style}>
      {words.map((word, index) => (
        <Fragment key={`${index}-${word}`}>
          {voiced ? (
            <span
              data-lily-voiced={index < (revealCount as number) ? 'true' : 'false'}
              style={{
                display: 'inline-block',
                opacity: index < (revealCount as number) ? 1 : 0,
                transform:
                  index < (revealCount as number) || reduce ? 'none' : 'translateY(2px)',
                transition: reduce ? 'none' : 'opacity 140ms ease, transform 140ms ease',
              }}
            >
              {word}
            </span>
          ) : (
            <span className="lily-word" style={{ animationDelay: `${index * 40}ms` }}>
              {word}
            </span>
          )}
          {index < words.length - 1 ? ' ' : null}
        </Fragment>
      ))}
    </p>
  );
}

